        let policy = RetentionPolicy {
            max_age_days: 0, // Expire immediately
            max_size_mb: 500,
        };

        cleanup_logs(dir.path(), &policy).unwrap();
        assert!(!old_file.exists(), "Old log file should have been deleted");
