//! Local template loading from user and project directories.

use crate::error::Result;
use crate::registry::template::{Template, TemplateSource};
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

/// Loader for local templates (user and project).
#[derive(Debug, Clone)]
pub struct LocalLoader {
    templates: HashMap<String, (Template, TemplateSource)>,
}

impl LocalLoader {
    /// Load templates from user and project directories.
    pub fn new(project_root: Option<&Path>) -> Result<Self> {
        let mut templates = HashMap::new();

        // Load user templates (~/.bivvy/templates/)
        if let Some(user_dir) = Self::user_templates_dir() {
            Self::load_from_dir(&user_dir, TemplateSource::User, &mut templates)?;
        }

        // Load project templates (.bivvy/templates/)
        if let Some(root) = project_root {
            let project_dir = root.join(".bivvy").join("templates");
            Self::load_from_dir(&project_dir, TemplateSource::Project, &mut templates)?;
        }

        Ok(Self { templates })
    }

    /// Get user templates directory.
    fn user_templates_dir() -> Option<PathBuf> {
        crate::sys::home_dir().map(|h| h.join(".bivvy").join("templates"))
    }

    /// Load templates from a directory (recursively).
    fn load_from_dir(
        dir: &Path,
        source: TemplateSource,
        templates: &mut HashMap<String, (Template, TemplateSource)>,
    ) -> Result<()> {
        if !dir.exists() {
            return Ok(());
        }

        // Load from steps/ subdirectory
        let steps_dir = dir.join("steps");
        if steps_dir.exists() {
            Self::load_templates_recursive(&steps_dir, source, templates)?;
        }

        Ok(())
    }

    fn load_templates_recursive(
        dir: &Path,
        source: TemplateSource,
        templates: &mut HashMap<String, (Template, TemplateSource)>,
    ) -> Result<()> {
        if !dir.is_dir() {
            return Ok(());
        }

        for entry in fs::read_dir(dir)? {
            let entry = entry?;
            let path = entry.path();

            if path.is_dir() {
                Self::load_templates_recursive(&path, source, templates)?;
            } else if path
                .extension()
                .map(|e| e == "yml" || e == "yaml")
                .unwrap_or(false)
            {
                let content = fs::read_to_string(&path)?;
                let template: Template = serde_yaml::from_str(&content).map_err(|e| {
                    crate::error::BivvyError::ConfigParseError {
                        path: path.clone(),
                        message: e.to_string(),
                    }
                })?;

                // Project templates override user templates
                let key = format!("{}/{}", template.category, template.name);
                if source == TemplateSource::Project || !templates.contains_key(&key) {
                    templates.insert(key, (template, source));
                }
            }
        }

        Ok(())
    }

    /// Get a template by name (unqualified — returns first match).
    pub fn get(&self, name: &str) -> Option<&Template> {
        // Try as qualified key first
        if let Some((t, _)) = self.templates.get(name) {
            return Some(t);
        }
        // Fall back to unqualified name match
        self.templates
            .values()
            .find(|(t, _)| t.name == name)
            .map(|(t, _)| t)
    }

    /// Get a template with its source (unqualified — returns first match).
    pub fn get_with_source(&self, name: &str) -> Option<(&Template, TemplateSource)> {
        // Try as qualified key first
        if let Some((t, s)) = self.templates.get(name) {
            return Some((t, *s));
        }
        // Fall back to unqualified name match
        self.templates
            .values()
            .find(|(t, _)| t.name == name)
            .map(|(t, s)| (t, *s))
    }

    /// Get a template with its source, filtering by category.
    pub fn get_with_source_by_category(
        &self,
        name: &str,
        category: &str,
    ) -> Option<(&Template, TemplateSource)> {
        let key = format!("{}/{}", category, name);
        self.templates.get(&key).map(|(t, s)| (t, *s))
    }

    /// Get all template names (qualified as `category/name`).
    pub fn template_names(&self) -> Vec<&str> {
        self.templates.keys().map(|s| s.as_str()).collect()
    }

    /// Check if a template exists (by unqualified name).
    pub fn has(&self, name: &str) -> bool {
        self.templates.contains_key(name) || self.templates.values().any(|(t, _)| t.name == name)
    }
}

