            "session": "sess_test",
            "type": "session_started",
            "command": "run",
            "args": [],
            "version": "1.9.0",
            "working_directory": "/no/longer/exists"
        });
        fs::write(&log_path, format!("{}\n", line)).unwrap();

        assert!(log_belongs_to_project(&log_path, &canonical));
    }
}

//! Snapshot and baseline management for change checks.
//!
//! The [`SnapshotStore`] manages baseline hashes used by change checks
//! to detect whether targets have changed. Baselines can be:
//! - Per-run (updated after each successful step execution)
//! - Named snapshots (captured via `bivvy snapshot <slug>`)
//!
//! Snapshots are stored per-project in `~/.bivvy/projects/{project_hash}/snapshots/`.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::PathBuf;

/// Describes what happened when a baseline was recorded.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum BaselineChange {
    /// A new baseline was established (no previous value existed).
    Established,
    /// The baseline was updated (previous hash differed).
    Updated {
        /// The previous hash value.
        old_hash: String,
    },
    /// The baseline hash was unchanged.
    Unchanged,
}

/// Key for looking up baselines in the snapshot store.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct SnapshotKey {
    /// Step name.
    pub step_name: String,
    /// Scope: "project" (default) or "workflow:{name}".
    pub scope: String,
    /// Hash of the step's check configuration. Ensures different
    /// check configs produce isolated baselines.
    pub config_hash: String,
}

impl SnapshotKey {
    /// Create a project-scoped key.
    pub fn project(step_name: impl Into<String>, config_hash: impl Into<String>) -> Self {
        Self {
            step_name: step_name.into(),
            scope: "project".to_string(),
            config_hash: config_hash.into(),
        }
    }

    /// Create a workflow-scoped key.
    pub fn workflow(
        step_name: impl Into<String>,
        workflow_name: impl Into<String>,
        config_hash: impl Into<String>,
    ) -> Self {
        Self {
            step_name: step_name.into(),
            scope: format!("workflow:{}", workflow_name.into()),
            config_hash: config_hash.into(),
        }
    }

    /// Returns the filename for this key's storage.
    fn filename(&self) -> String {
        if self.scope == "project" {
            format!("{}_{}.yml", self.step_name, self.config_hash)
        } else {
            let workflow = self.scope.strip_prefix("workflow:").unwrap_or("unknown");
            format!(
                "{}_{}__wf_{}.yml",
                self.step_name, self.config_hash, workflow
            )
        }
    }
}

/// Information about a single baseline.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BaselineEntry {
    /// The computed hash.
    pub hash: String,
    /// When this baseline was captured.
    pub captured_at: String,
    /// What was hashed.
    pub target: String,
}

/// Stored snapshot data for a step.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct SnapshotData {
    /// Step name.
    pub step: String,
    /// Scope.
    pub scope: String,
    /// Named and run-based baselines.
    #[serde(default)]
    pub baselines: HashMap<String, BaselineEntry>,
}

/// Information about a named snapshot for listing.
#[derive(Debug, Clone)]
pub struct SnapshotInfo {
    /// The snapshot slug.
    pub slug: String,
    /// Step name.
    pub step: String,
    /// Target that was hashed.
    pub target: String,
    /// Hash value.
    pub hash: String,
    /// When captured.
    pub captured_at: String,
}

/// A recorded baseline change, for event emission.
#[derive(Debug, Clone)]
pub struct BaselineEvent {
    /// Step name.
    pub step: String,
    /// What was hashed (file path, glob, command).
    pub target: String,
    /// New hash value.
    pub hash: String,
    /// Scope ("project" or "workflow:<name>").
    pub scope: String,
    /// What kind of change occurred.
    pub change: BaselineChange,
}

/// Manages baseline hashes for change check comparisons.
///
/// The store reads/writes YAML files in a snapshots directory.
/// Each step+config combination gets its own file.
pub struct SnapshotStore {
    /// Directory where snapshot files are stored.
    dir: PathBuf,
    /// In-memory cache of loaded snapshot data.
    cache: HashMap<String, SnapshotData>,
    /// Pending baseline changes for event emission.
    pending_events: Vec<BaselineEvent>,
}

impl SnapshotStore {
    /// Create a new store backed by the given directory.
    pub fn new(dir: impl Into<PathBuf>) -> Self {
        Self {
            dir: dir.into(),
            cache: HashMap::new(),
            pending_events: Vec::new(),
        }
    }

    /// Create an empty in-memory store not backed by any directory.
    ///
    /// Useful when check evaluation doesn't need snapshot storage
    /// (e.g., evaluating presence or execution checks only).
    /// Change checks evaluated against this store will always get
    /// `None` baselines (indeterminate results).
    pub fn empty() -> Self {
        Self {
            dir: PathBuf::new(),
            cache: HashMap::new(),
            pending_events: Vec::new(),
        }
    }

    /// Load or create a snapshot store for a project.
    ///
    /// Uses the platform data directory under
    /// `bivvy/projects/{project_hash}/snapshots/`, matching the state
    /// store's project isolation scheme.
    pub fn load_for_project(project_id: &crate::state::ProjectId) -> Self {
        let dir = crate::sys::bivvy_data_dir()
            .unwrap_or_else(|| PathBuf::from("bivvy"))
            .join("projects")
            .join(project_id.hash())
            .join("snapshots");
        Self::new(dir)
    }

    /// Get the baseline hash for a change check.
    ///
    /// The `baseline_name` parameter selects which baseline to compare against:
    /// - `"_last_run"` for `each_run` baseline config
    /// - `"_first_run"` for `first_run` baseline config
    /// - A named slug for `snapshot:<slug>` baseline config
    pub fn get_baseline(&mut self, key: &SnapshotKey, baseline_name: &str) -> Option<String> {
        self.ensure_loaded(key);
        let filename = key.filename();
        self.cache
            .get(&filename)
            .and_then(|data| data.baselines.get(baseline_name))
            .map(|entry| entry.hash.clone())
    }

    /// Record a new baseline after successful step execution.
    ///
    /// Returns [`BaselineChange`] indicating whether this was a new baseline
    /// or an update to an existing one (with the old hash).
    pub fn record_baseline(
        &mut self,
        key: &SnapshotKey,
        baseline_name: &str,
        hash: String,
        target: String,
    ) -> BaselineChange {
        self.ensure_loaded(key);
        let filename = key.filename();
        let data = self.cache.entry(filename).or_insert_with(|| SnapshotData {
            step: key.step_name.clone(),
            scope: key.scope.clone(),
            baselines: HashMap::new(),
        });

        let change = match data.baselines.get(baseline_name) {
            None => BaselineChange::Established,
            Some(existing) if existing.hash == hash => BaselineChange::Unchanged,
            Some(existing) => BaselineChange::Updated {
                old_hash: existing.hash.clone(),
            },
        };

        if !matches!(change, BaselineChange::Unchanged) {
            self.pending_events.push(BaselineEvent {
                step: key.step_name.clone(),
                target: target.clone(),
                hash: hash.clone(),
                scope: key.scope.clone(),
                change: change.clone(),
            });
        }

        data.baselines.insert(
            baseline_name.to_string(),
            BaselineEntry {
                hash,
                captured_at: now_iso8601(),
                target,
            },
        );

        change
    }

    /// Drain pending baseline change events.
    ///
    /// Returns all baseline changes that occurred since the last drain.
    /// The orchestrator calls this after check evaluation to emit
    /// `BaselineEstablished` / `BaselineUpdated` events.
    pub fn drain_events(&mut self) -> Vec<BaselineEvent> {
        std::mem::take(&mut self.pending_events)
    }

    /// Capture a named snapshot.
    pub fn capture_named(&mut self, key: &SnapshotKey, slug: &str, hash: String, target: String) {
        self.record_baseline(key, slug, hash, target);
    }

    /// List all named snapshots (excludes internal baselines like _last_run).
    pub fn list_named(&mut self) -> Vec<SnapshotInfo> {
        self.load_all();
        let mut result = Vec::new();
        for data in self.cache.values() {
            for (name, entry) in &data.baselines {
                if !name.starts_with('_') {
                    result.push(SnapshotInfo {
                        slug: name.clone(),
                        step: data.step.clone(),
                        target: entry.target.clone(),
                        hash: entry.hash.clone(),
                        captured_at: entry.captured_at.clone(),
                    });
                }
            }
        }
        result.sort_by(|a, b| a.slug.cmp(&b.slug));
        result
    }

    /// Delete a named snapshot.
    pub fn delete_named(&mut self, slug: &str) -> bool {
        self.load_all();
        let mut found = false;
        for data in self.cache.values_mut() {
            if data.baselines.remove(slug).is_some() {
                found = true;
            }
        }
        found
    }

    /// Save all modified data to disk.
    pub fn save(&self) -> std::io::Result<()> {
        std::fs::create_dir_all(&self.dir)?;
        for (filename, data) in &self.cache {
            let path = self.dir.join(filename);
            let yaml = serde_yaml::to_string(data).map_err(std::io::Error::other)?;
            std::fs::write(path, yaml)?;
        }
        Ok(())
    }

    /// Load snapshot data for a key if not already cached.
    fn ensure_loaded(&mut self, key: &SnapshotKey) {
        let filename = key.filename();
        if self.cache.contains_key(&filename) {
            return;
        }
        let path = self.dir.join(&filename);
        if path.exists() {
            if let Ok(contents) = std::fs::read_to_string(&path) {
                if let Ok(data) = serde_yaml::from_str::<SnapshotData>(&contents) {
                    self.cache.insert(filename, data);
                    return;
                }
            }
        }
        // Initialize empty
        self.cache.insert(
            filename,
            SnapshotData {
                step: key.step_name.clone(),
                scope: key.scope.clone(),
                baselines: HashMap::new(),
            },
        );
    }

    /// Load all snapshot files from disk.
    fn load_all(&mut self) {
        if !self.dir.exists() {
            return;
        }
        if let Ok(entries) = std::fs::read_dir(&self.dir) {
            for entry in entries.flatten() {
                let path = entry.path();
                if path.extension().is_some_and(|e| e == "yml") {
                    let filename = path
                        .file_name()
                        .unwrap_or_default()
                        .to_string_lossy()
                        .to_string();
                    if self.cache.contains_key(&filename) {
                        continue;
                    }
                    if let Ok(contents) = std::fs::read_to_string(&path) {
                        if let Ok(data) = serde_yaml::from_str::<SnapshotData>(&contents) {
                            self.cache.insert(filename, data);
                        }
                    }
                }
            }
        }
    }
}

fn now_iso8601() -> String {
    chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis, true)
}

