        let mut store = SnapshotStore::new(temp.path());

        let key1 = SnapshotKey::project("step", "config_a");
        let key2 = SnapshotKey::project("step", "config_b");

        store.record_baseline(
            &key1,
            "_last_run",
            "sha256:a".to_string(),
            "file.txt".to_string(),
        );
        store.record_baseline(
            &key2,
            "_last_run",
            "sha256:b".to_string(),
            "file.txt".to_string(),
