            Some("sha256:b".to_string())
        );
    }

    #[test]
    fn empty_dir_load_all_works() {
        let temp = TempDir::new().unwrap();
        let mut store = SnapshotStore::new(temp.path());
        let named = store.list_named();
        assert!(named.is_empty());
    }
