        });

        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();

        // Project config extends base
        fs::write(
            bivvy_dir.join("config.yml"),
            format!(
                r#"
extends:
  - url: {}
app_name: ProjectApp
"#,
                server.url("/base.yml")
            ),
        )
        .unwrap();

        // Local override file overrides app_name
        fs::write(
